function ct_gate():void{if(crm_query("SELECT state FROM nd_schema_migrations WHERE version='019_contract_details'")->fetchColumn()!=='applied')crm_fail(503,'Формы реквизитов ещё не подготовлены.');}
function ct_owner_labels():array{return ['full_name'=>'ФИО исполнителя','inn'=>'ИНН','status'=>'Статус: npd или ip_npd','ogrnip'=>'ОГРНИП (только ИП)','email'=>'Рабочая электронная почта','phone'=>'Телефон (необязательно)','max'=>'Личная ссылка MAX (необязательно)','telegram'=>'Ссылка Telegram (необязательно)','postal_address'=>'Почтовый адрес для корреспонденции (необязательно)','recipient'=>'Получатель платежа','bank'=>'Название банка','account'=>'Номер счёта','bik'=>'БИК','corr'=>'Корреспондентский счёт'];}
function ct_party_labels():array{return ['type'=>'Тип заказчика','name'=>'ФИО / наименование','email'=>'Email','purpose'=>'Цель: personal / business','inn'=>'ИНН','ogrn'=>'ОГРН','ogrnip'=>'ОГРНИП','kpp'=>'КПП (при наличии)','address'=>'Юридический адрес организации','signatory'=>'ФИО подписанта','position'=>'Должность подписанта','authority'=>'Основание полномочий','represented'=>'Действует представитель','contact'=>'Дополнительный контакт (необязательно)','postal_address'=>'Почтовый адрес (необязательно)','bank_details'=>'Реквизиты, только если нужны для сделки'];}
function ct_strings(mixed $data,array $labels):array{if(!is_array($data)||array_diff(array_keys($data),array_keys($labels)))crm_fail(422,'Неизвестное поле реквизитов.');$out=[];foreach($labels as $k=>$v)$out[$k]=cc_text($data,$k,2500,false);return $out;}
function ct_ogrn(string $v,int $n):bool{if(!preg_match('/^[0-9]{'.$n.'}$/D',$v)||preg_match('/^0+$/D',$v))return false;$mod=$n===13?11:13;$rem=0;foreach(str_split(substr($v,0,-1)) as $d)$rem=($rem*10+(int)$d)%$mod;return $rem%10===(int)$v[$n-1];}
function ct_iso_date(string $v):bool{$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);return $d!==false&&$d->format('Y-m-d')===$v;}
function ct_email(string $v):void{if(strlen($v)>190||!filter_var($v,FILTER_VALIDATE_EMAIL))crm_fail(422,'Проверьте email.');}
function ct_required(array $d,array $keys):void{foreach($keys as $k)if(trim($d[$k]??'')==='')crm_fail(422,'Не заполнено: '.$k);}
function ct_bank(array $d):void{
 foreach(['account'=>20,'bik'=>9,'corr'=>20] as $k=>$n)if(!preg_match('/^[0-9]{'.$n.'}$/D',$d[$k]))crm_fail(422,'Проверьте длину: '.$k);
 foreach(['account'=>substr($d['bik'],-3),'corr'=>'0'.substr($d['bik'],4,2)] as $k=>$prefix){$sum=0;foreach(str_split($prefix.$d[$k]) as $i=>$digit)$sum+=(int)$digit*[7,1,3][$i%3];if($sum%10!==0)crm_fail(422,'Контрольная сумма банковских реквизитов: '.$k);}
}
function ct_validate_owner(array $d):void{
 ct_required($d,['full_name','inn','status','email','recipient','bank','account','bik','corr']);if(strlen($d['inn'])!==12||!lc_inn_valid($d['inn']))crm_fail(422,'Некорректный ИНН исполнителя.');if(!in_array($d['status'],['npd','ip_npd'],true))crm_fail(422,'Выберите статус НПД.');if($d['status']==='ip_npd'&&!ct_ogrn($d['ogrnip'],15))crm_fail(422,'Некорректный ОГРНИП.');ct_email($d['email']);ct_bank($d);
 foreach(['max'=>'max.ru','telegram'=>'t.me'] as $k=>$host)if($d[$k]!==''&&(parse_url($d[$k],PHP_URL_SCHEME)!=='https'||parse_url($d[$k],PHP_URL_HOST)!==$host||parse_url($d[$k],PHP_URL_USER)!==null||parse_url($d[$k],PHP_URL_PASS)!==null))crm_fail(422,'Проверьте ссылку '.$k);
}
function ct_validate_party(array $d):void{
 ct_required($d,['type','name','email']);ct_email($d['email']);if(!in_array($d['type'],['person','ip','company'],true))crm_fail(422,'Выберите тип заказчика.');
 if($d['type']==='person'&&!in_array($d['purpose'],['personal','business'],true))crm_fail(422,'Укажите цель использования. Она не отменяет обязательных прав.');
 if($d['type']!=='person'){if(strlen($d['inn'])!==($d['type']==='company'?10:12)||!lc_inn_valid($d['inn']))crm_fail(422,'Некорректный ИНН.');$key=$d['type']==='company'?'ogrn':'ogrnip';if(!ct_ogrn($d[$key],$d['type']==='company'?13:15))crm_fail(422,'Некорректный '.$key);}
