function ct_owner_save(array $d):array{$data=ct_strings($d['data']??[],ct_owner_labels());$review=($d['reviewed']??false)===true;$latest=crm_query('SELECT id FROM nd_lc_owner_profiles ORDER BY id DESC LIMIT 1 FOR UPDATE')->fetchColumn();if((int)$latest!==(int)($d['prior_id']??0))crm_fail(409,'Реквизиты изменились. Перезагрузите форму.');if($review)ct_validate_owner($data);$hash=hash('sha256',lc_json($data));crm_query('INSERT INTO nd_lc_owner_profiles(data_json,checksum,reviewed) VALUES (?,?,?)',[lc_json($data),$hash,$review?1:0]);$id=(int)db()->lastInsertId();lc_audit(['type'=>'owner','id'=>1],'owner_profile',$id,$review?'reviewed':'draft_saved',null,['hash'=>$hash,'external_identity_verified'=>false]);return ['ok'=>true,'id'=>$id];}
