 crm_record('orders',(int)$s['order_id'],true);$prior=crm_query('SELECT * FROM nd_lc_customer_details WHERE order_id=? ORDER BY id DESC LIMIT 1 FOR UPDATE',[$s['order_id']])->fetch();if((int)($prior['id']??0)!==(int)($d['prior_id']??0))crm_fail(409,'Данные изменились. Обновите форму.');$data=ct_strings($d['data']??[],ct_party_labels());if($data['type']==='person'){foreach(['inn','ogrn','ogrnip','kpp','address','position'] as $unused)$data[$unused]='';}if($data['type']==='ip'){foreach(['ogrn','kpp','address','purpose'] as $unused)$data[$unused]='';}if($data['type']==='company'){$data['purpose']='';$data['ogrnip']='';}if($data['type']!=='company'&&$data['represented']!=='yes'){$data['signatory']='';$data['position']='';$data['authority']='';}$submit=($d['submit']??false)===true;if($submit)ct_validate_party($data);$hash=hash('sha256',lc_json($data));crm_query('INSERT INTO nd_lc_customer_details(order_id,link_id,data_json,checksum,state) VALUES (?,?,?,?,?)',[$s['order_id'],$s['link_id'],lc_json($data),$hash,$submit?'SUBMITTED':'DRAFT']);$id=(int)db()->lastInsertId();ps_event((int)$s['link_id'],'prospect',$submit?'details_submitted':'details_draft_saved',['id'=>$id,'hash'=>$hash,'email_verified'=>false,'signature'=>false]);if($submit)crm_notice('contract-details:'.$id,'orders',(int)$s['order_id'],'Проверьте данные для договора и полномочия подписанта.');return ['ok'=>true,'id'=>$id,'email_verified'=>false,'account_created'=>false];
